const { z } = require("zod");
function symptom(m) { console.error("FAIL: " + m); process.exit(1); }
function broken(m) { console.error("ERROR: " + m); process.exit(2); }
if (!z.locales || typeof z.locales.fr !== "function") broken("z.locales.fr is missing");
z.config(z.locales.fr());
const r = z.number().max(10).safeParse(15);
if (r.success) broken("z.number().max(10) accepted 15");
const msg = r.error.issues[0].message;
if (msg === "Trop grand : number doit être <=10") symptom("z.locales.fr too_big message shows the untranslated origin number");
if (msg !== "Trop grand : nombre doit être <=10") broken("unexpected message: " + msg);
console.log("OK: " + msg);

